def ternary_search(arr, to_find):

    left = 0
    right = len(arr) - 1
    while left <= right:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3
        if arr[mid1] == to_find:
            return mid1
        elif arr[mid2] == to_find:
            return mid2
        elif to_find < arr[mid1]:
            right = mid1 - 1
        elif to_find > arr[mid2]:
