import math

def compute_sector_area(data, sector_type):


    if sector_type not in ['circle', 'sphere']:
        return "Invalid sector type. Please give either 'circle' or 'sphere'."

    surface_areas = []

    for radius, angle in data:
        if angle > 360 or angle < 0:
            surface_areas.append(None)
            continue

        if radius < 0:
            return "Invalid radius. Radius cannot be negative."

        if sector_type == 'circle':
            # formula for area of sector of circle = (pi.R^2.(Angle/360))
            area = round((math.pi * radius ** 2 * (angle / 360)), 2)
        else:
            # formula for surface area of sector of sphere = 2.pi.R.(Angle/360).R
            area = round((2 * math.pi * radius * (angle / 360) * radius), 2)

        surface_areas.append(area)

