def serialize(obj):

    if isinstance(obj, dict):
        serialized_obj = "{"
        for index, (key, value) in enumerate(obj.items()):
            serialized_obj += '"' + str(key) + '":'
            serialized_obj += serialize(value)
            if index < len(obj) - 1:
