def max_path_sum(root):

    memo = {}

    def dfs(node):
        if not node:
            return 0

        if node in memo:
            return memo[node]

        left_sum = max(dfs(node.left), 0)
        right_sum = max(dfs(node.right), 0)

        memo[node] = node.val + left_sum + right_sum

        return memo[node]

    return dfs(root)

