my_string = "abcabcbb"

def max_length_substr(my_string):

    known_substrings = {}
    max_length = 0
    start, end = 0, 0
    while end < len(my_string):
        curr_char = my_string[end]
        if curr_char in known_substrings:
            start = max(start, known_substrings[curr_char] + 1)
        max_length = max(max_length, end - start + 1)
        known_substrings[curr_char] = end
        end += 1
    return max_length

