def partition(n):

    answer = []
    # base case, no elements
    if n == 0:
        answer.append([])
        return answer

    if n == 1:
        answer.append([1])
        return answer

    # Recursive case
    for i in range(n, 0, -1):
        partition_list = partition(n - i)
        for result in partition_list:
            new_result = result + [i]
            answer.append(new_result)

    return answer

