def knapsack(num_items, capacity, weights, values):

    n = num_items
    W = capacity
    V = [[0 for x in range(W+1)] for x in range(n+1)]

    for i in range(1, n+1):
        for w in range(1, W+1):
            if weights[i-1] <= w:
                V[i][w] = max(V[i-1][w], values[i-1] + V[i-1][w-weights[i-1]])
            else:
                V[i][w] = V[i-1][w]

    return V[n][W]

