def knapsack(items, capacity): 

    n = len(items)
    # initializing a 2D array for caching 
    values = [[0 for _ in range(capacity+1)] for _ in range(n+1)] 
    for i in range(1, n+1): 
        for w in range(1, capacity+1): 
            if items[i-1].weight <= w:
                values[i][w] = max(items[i-1].value + values[i-1][w-items[i-1].weight], values[i-1][w]) 
            else:
                values[i][w] = values[i-1][w] 
    # find the maximum value 
    max_value = values[n][capacity] 
    # find the selected items from knapsack
    curr_capacity = capacity
    items_in_knapsack = []
    for items in reversed(range(n)):
        if values[items][curr_capacity] != values[items-1][curr_capacity]:
            items_in_knapsack.append(items)
            curr_capacity -= items[items-1].weight
    return (max_value, items_in_knapsack)

