def find_islands(mat):

    visited = set()
    queue = []
    queue.append((start_x, start_y))
    island = []

    while queue:
        (x, y) = queue.pop(0)
        if (x, y) not in visited:
            visited.add((x, y))
            island.append((x, y))
            up = (x - 1, y)
            if 0 <= up[0] < len(mat) and mat[up[0]][y] == 1 and up not in visited:
                queue.append(up)
            down = (x + 1, y)
            if 0 <= down[0] < len(mat) and mat[down[0]][y] == 1 and down not in visited:
