import re

def evaluate(expression):

    def apply_op(op, b, a):
        if op=='+': 
            return a + b
        elif op=='-': 
            return a - b
        elif op=='*': 
            return a * b
        elif op=='^': 
            return a ** b
        else:  # operator is '/'
            return a / b

    def precedence(op):
        if op=='+' or op=='-':
            return 1
        if op=='*' or op=='/':
            return 2
        if op=='^':
            return 3
        return 0

    data = []
    ops = []
    expression = re.split("([^0-9.])", expression.replace(" ", ""))
    for x in expression:
        if x.isdigit() or "." in x:
            data.append(float(x))
        elif x=="(":
            ops.append(x)
        elif x==")":
            while ops[-1] != "(":
                data.append(apply_op(ops.pop(), data.pop(), data.pop()))
            ops.pop()  # Remove '('
        else:
            while (len(ops) != 0 and 
                   precedence(x) <= precedence(ops[-1])):
                data.append(apply_op(ops.pop(), data.pop(), data.pop()))
            ops.append(x)

    while len(ops) != 0:
        data.append(apply_op(ops.pop(), data.pop(), data.pop()))

