def G(N):

    neg_ones, zeros, ones = 0, 0, 0
    for n in range(1, N+1):
        last = -1 * (n%2) * n
        if last == -1:
            neg_ones += 1
        elif last == 0:
            zeros += 1
        elif last == 1:
            ones += 1
    return -1 * neg_ones + zeros + 1 * ones

def findTarget(nums, target):

    row, col = len(nums), len(nums[0])
    lo, hi = 0, row*col
    while lo < hi:
        mid = (lo + hi) // 2
        x = nums[mid // col][mid % col]
        if x < target:
            lo = mid + 1
        elif x > target:
            hi = mid 
        else:
            return (mid // col, mid % col) # Return position in row,column format
