def find_max_diff(nums):

    if not nums:
        return None

    max_diff = nums[1] - nums[0]
    min_element = nums[0]
    min_index = 0
    result = (0, 1)

    for i in range(1, len(nums)):
        if nums[i] - min_element > max_diff:
            max_diff = nums[i] - min_element
            result = (min_index, i)

        if nums[i] < min_element:
            min_element = nums[i]
            min_index = i

    return result, max_diff

