        crush = set()
        # check for crushes
        for r in range(len(board)):
            for c in range(len(board[r])):
                if board[r][c] == 0:
                    continue
                for d in range(4):
                    nj, ni, nx = c, r, []
                    while 0 <= ni < len(board) and 0 <= nj < len(board[0]) and board[ni][nj] == board[r][c]:
                        nx.append((ni, nj))
                        ni += directions[d]
                        nj += directions[d + 1]
                    if len(nx) >= 3:
                        crush |= set(nx)
        # if no more crushes exit
        if not crush:
            break
        # crush
        for r, c in crush:
            board[r][c] = 0
        # drop
        for r, c in sorted(((r, c) for r in range(len(board)) for c in range(len(board[0])) if board[r][c] == 0), reverse=True):
            ni = r
            while ni - 1 >= 0 and board[ni - 1][c] != 0:
