def quicksort(arr):

    if len(arr) <= 1:
        return arr
    else:
        pivot = arr.pop()

    items_greater = []
    items_lower = []

    for item in arr:
        if item > pivot:
            items_greater.append(item)
        else:
            items_lower.append(item)

    return quicksort(items_lower) + [pivot] + quicksort(items_greater)

def longest_consec_sequence(lst):

    max_length, max_index = 0, -1
    current_length, current_index = 1, 0
    for i in range(1, len(lst)):
        if lst[i] - lst[i - 1] == 1:
            current_length += 1
        else:
