def flower_pots(n, k):

    mod = 10**9 + 7
    if n == 1:
        return k
    dp = [[0]*(n+1) for _ in range(n+1)]
    dp[1][0], dp[1][1] = k, 0
    for i in range(2, n+1):
        dp[i][0] = dp[i-1][0]*(k-1)%mod
        dp[i][i-1] = dp[i-1][i-2]*(k-1)%mod
        dp[i][i] = dp[i-1][i-1]
        for j in range(1, i-1):
            dp[i][j] = (dp[i-1][j-1] + dp[i-1][j]*(k-j))%mod
    return sum(dp[-1])%mod

