def replace_alternating_repeat_values(elements_list, replace_value):

    seen_indices = {}
    for i in range(len(elements_list)):
        if elements_list[i] not in seen_indices:
            # If the value hasn't been seen before, remember the index
            seen_indices[elements_list[i]] = i
        elif (i - seen_indices[elements_list[i]]) % 2 == 1:
            # If the value is an "alternating repeat", replace it,
            # and forget the previous index (so that a third identical
            # value in a row won't be replaced)
            elements_list[i] = replace_value
            del seen_indices[elements_list[i]]
    return elements_list

