    if the_length == 1:
        return nums
    elif the_length == 2:
        if nums[1] < nums[0]:
            nums[0], nums[1] = nums[1], nums[0]
        return nums
    else:
        low_list = []
        high_list = []
        final_list = []
        piv_low = nums[0]
