    if path is None:
        path = []
    for key in b:
        if key in a:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                deep_merge(a[key], b[key], overwrite, path + [str(key)])
            elif not overwrite or a[key] == b[key]:
