def substitute_name(pattern, name, left_side):

    def sub(s):
        text = s.group(1)
        if text == 'name':
            return name

        if '|' in text:
            parts = text.split('|', 2)
            if left_side or len(parts) == 1:
                return parts[0]
            else:
                return parts[1]

        return s.group(0)
    return re.sub(r'<([^>]*)>', sub, pattern)

