            nonlocal done
            for j in range(n):
                if a[j] == 0:
                    a[j] = z
                    done = True
                    break
                else:
                    if a[j] > z:
                        swap(j)
                        a[j] = z
                    else:
                        done = False
                        break

        for i in range(n):
            for j in range(n):
                if abs(i - j) == k:
                    if a[j] == 0:
                        a[j] = i + 1
                        done = True
                        break
                    else:
                        if a[j] > i + 1:
                            swap(a[j])
                            a[j] = i + 1
                        else:
                            done = False

