def last_digit_of_prime_sum(n):
    prime = [True] * (n + 1)
    prime[0], prime[1] = False, False

    p = 2
    while p * p <= n:
        if prime[p] == True:
            for i in range(p * 2, n + 1, p):
                prime[i] = False
        p += 1

    total_sum = 0
    for i in range(2, n + 1):
        if prime[i]:
            total_sum += i

    return total_sum % 10

