def compute_total_volume(rows, columns, forest, queries):
    matrix = [[0 for _ in range(columns)] for _ in range(rows)]

    # Calculate cumulative sum matrix
    for i in range(rows):
        for j in range(columns):
            matrix[i][j] = forest[i][j]
            if i > 0:
                matrix[i][j] += matrix[i - 1][j]
            if j > 0:
                matrix[i][j] += matrix[i][j - 1]
            if i > 0 and j > 0:
                matrix[i][j] -= matrix[i - 1][j - 1]

    results = []

    # Process each query
    for query in queries:
        x1, y1, x2, y2 = query
        x1 -= 1
        y1 -= 1
        x2 -= 1
        y2 -= 1

        total_volume = matrix[x2][y2]
        if x1 > 0:
            total_volume -= matrix[x1 - 1][y2]
        if y1 > 0:
            total_volume -= matrix[x2][y1 - 1]
        if x1 > 0 and y1 > 0:
            total_volume += matrix[x1 - 1][y1 - 1]

        results.append(total_volume)

    return results

