            tidx = i
            break

    if tidx < 0:
        return A

    sidx = -1
    for j in range(n-1, tidx, -1):
        if A[j] < A[tidx]:
            sidx = j
            break

    A[tidx], A[sidx] = A[sidx], A[tidx]

