        v = num1 + num2
        v *= num1 * num1 + num2 * num2
        v %= p
        v += p
        v %= p
        return v == k % p

    idx_precount = [((x ** 4 - k * x) % p + p) % p for x in numbers]

    met_precount_vals = {}
    ans = 0
    for number, precount in zip(numbers[::-1], idx_precount[::-1]):
        if precount not in met_precount_vals:
            met_precount_vals[precount] = []
        else:
            for val in met_precount_vals[precount]:
                if check(number, val, p, k):
                    ans += 1
        met_precount_vals[precount].append(number)
    return ans

