def group(arr):
    # Initialize an empty list to store the result
    result = []

    # Create a set to keep track of unique numbers
    unique_nums = set()

    # Iterate through the input array
    for num in arr:
        # If the number is not in the unique set, add it to the set and create a new subarray in the result
        if num not in unique_nums:
            unique_nums.add(num)
            result.append([num])
        # If the number is already in the set, find the corresponding subarray and append the number to it
        else:
