def crack_cthulhus_code(i, k, s, a_i, b_i):
    import math

    x = math.sqrt(2)
    y = math.sqrt(3)

    if i <= k:
        diff = k - i
        if (k - i) % 2 == 0:
            ans = (a_i + b_i) * math.pow(2, 2 * (k - i) - s)
        else:
            ans = (2 * x * a_i + 2 * x * y * b_i) * math.pow(2, 4 * (diff // 2) - s)
    else:
        diff = i - k
        if (i - k) % 2 == 0:
            ans = (a_i + b_i) / math.pow(2, 2 * (i - k) + s)
        else:
            ans = (2 * x * a_i + 2 * x * y * b_i) / math.pow(2, 4 * (diff // 2) + 4 + s)

    return ans

