        return "now"

    units = [
        (31536000, "year"),
        (86400, "day"),
        (3600, "hour"),
        (60, "minute"),
        (1, "second")
    ]

    time_chunks = []
    for unit in units:
        count, seconds = divmod(seconds, unit[0])
        if count:
            time_str = "{} {}".format(count, unit[1] + "s" if count > 1 else unit[1])
            time_chunks.append(time_str)

    if len(time_chunks) > 1:
        return ", ".join(time_chunks[:-1]) + " and " + time_chunks[-1]
