def count_smeagolese_anagrams(t, words):
    from collections import Counter
    from math import factorial

    results = []
    for i in range(t):
        s = words[i]
        c = Counter(s)
        k = factorial(len(s))
        for value in c.values():
            if value > 1:
                k = k // factorial(value)
        results.append(k % (10**9 + 7))

    return results

